// ValidateAttributeMetadataResponseBody runs the validations defined on
// AttributeMetadataResponseBody
func ValidateAttributeMetadataResponseBody(body *AttributeMetadataResponseBody) (err error) {
	if body.LastUpdated != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.last_updated", *body.LastUpdated, goa.FormatDateTime))
	}
	if body.Confidence != nil {
		if *body.Confidence < 0 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("body.confidence", *body.Confidence, 0, true))
		}
	}
	if body.Confidence != nil {
		if *body.Confidence > 1 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("body.confidence", *body.Confidence, 1, false))
		}
	}
	if body.ExpiresAt != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.expires_at", *body.ExpiresAt, goa.FormatDateTime))
	}
	if body.VerificationMethod != nil {
		if !(*body.VerificationMethod == "system_sync" || *body.VerificationMethod == "manual_assignment" || *body.VerificationMethod == "computed" || *body.VerificationMethod == "self_reported") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.verification_method", *body.VerificationMethod, []any{"system_sync", "manual_assignment", "computed", "self_reported"}))
		}
	}
	if body.DataClassification != nil {
		if !(*body.DataClassification == "public" || *body.DataClassification == "internal" || *body.DataClassification == "confidential" || *body.DataClassification == "restricted") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.data_classification", *body.DataClassification, []any{"public", "internal", "confidential", "restricted"}))
		}
	}
	return
}

